import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { crearPedido, getUsuario } from '../services/api';
import './Pago.css';
import '../App.css';

function Pago() {
    const navigate = useNavigate();
    const usuario = getUsuario();
    const [carrito, setCarrito] = useState(null);
    const [metodoPago, setMetodoPago] = useState('efectivo');
    const [procesando, setProcesando] = useState(false);
    const [idioma] = useState(localStorage.getItem('idioma') || 'es');

    const textos = {
        es: {
            titulo: 'Finalizar Pago',
            resumen: 'Resumen del Pedido',
            total: 'Total a Pagar',
            metodo: 'Método de Pago',
            efectivo: 'Efectivo',
            tarjeta: 'Tarjeta',
            procesar: 'Confirmar y Pagar',
            procesando: 'Procesando...',
            volver: 'Volver al Menú',
            exito: '¡Pedido realizado con éxito!',
            error: 'Hubo un error al procesar el pedido.',
            vacio: 'El carrito está vacío.',
            subtotal: 'Subtotal',
            impuesto: 'IGIC (7%)',
            centro: 'Punto de Recogida'
        },
        en: {
            titulo: 'Checkout',
            resumen: 'Order Summary',
            total: 'Total to Pay',
            metodo: 'Payment Method',
            efectivo: 'Cash',
            tarjeta: 'Card',
            procesar: 'Confirm and Pay',
            procesando: 'Processing...',
            volver: 'Back to Menu',
            exito: 'Order placed successfully!',
            error: 'There was an error processing the order.',
            vacio: 'Cart is empty.',
            subtotal: 'Subtotal',
            impuesto: 'Tax (7%)',
            centro: 'Collection Point'
        }
    };

    const t = textos[idioma];

    useEffect(() => {
        const carritoGuardado = localStorage.getItem('carrito');
        if (carritoGuardado) {
            setCarrito(JSON.parse(carritoGuardado));
        } else {
            navigate('/home');
        }
    }, [navigate]);

    const handlePago = async () => {
        if (!carrito || procesando) return;

        setProcesando(true);
        try {
            const datosPedido = {
                usuario_id: usuario.id,
                total: carrito.total,
                items: carrito.items,
                metodo_pago: metodoPago,
                centro: usuario.centro || 'IES José Zerpa'
            };

            await crearPedido(datosPedido);
            alert(t.exito);
            localStorage.removeItem('carrito');
            navigate('/home');
        } catch (error) {
            console.error('Error en el pago:', error);
            alert(t.error);
        } finally {
            setProcesando(false);
        }
    };

    if (!carrito) return null;

    return (
        <div className="App">
            <header className="App-header">
                <div className="header-container">
                    <div className="title">CafES App</div>
                </div>
            </header>

            <main className="App-main pago-container">
                <div className="checkout-card shadow-lg">
                    <h2 className="checkout-title">{t.titulo}</h2>

                    <div className="checkout-section">
                        <h3>{t.resumen}</h3>
                        <div className="checkout-items">
                            {carrito.items.map((item, idx) => (
                                <div key={idx} className="checkout-item">
                                    <div className="item-info">
                                        <span className="item-qty">{item.cantidad}x</span>
                                        <span className="item-name">{item.nombre}</span>
                                    </div>
                                    <span className="item-price">{(item.cantidad * item.precio).toFixed(2)}€</span>
                                </div>
                            ))}
                        </div>
                    </div>

                    <div className="checkout-divider"></div>

                    <div className="checkout-section">
                        <div className="checkout-totals">
                            <div className="total-row">
                                <span>{t.subtotal}</span>
                                <span>{carrito.subtotal}€</span>
                            </div>
                            <div className="total-row">
                                <span>{t.impuesto}</span>
                                <span>{carrito.impuesto}€</span>
                            </div>
                            <div className="total-row grand-total">
                                <span>{t.total}</span>
                                <span>{carrito.total}€</span>
                            </div>
                        </div>
                    </div>

                    <div className="checkout-section">
                        <h3>{t.metodo}</h3>
                        <div className="payment-methods">
                            <button
                                className={`method-btn ${metodoPago === 'efectivo' ? 'active' : ''}`}
                                onClick={() => setMetodoPago('efectivo')}
                            >
                                <span className="method-icon">💵</span>
                                {t.efectivo}
                            </button>
                            <button
                                className={`method-btn ${metodoPago === 'tarjeta' ? 'active' : ''}`}
                                onClick={() => setMetodoPago('tarjeta')}
                            >
                                <span className="method-icon">💳</span>
                                {t.tarjeta}
                            </button>
                        </div>
                    </div>

                    <div className="checkout-section info-section">
                        <p><strong>{t.centro}:</strong> {usuario?.centro || 'IES José Zerpa'}</p>
                    </div>

                    <div className="checkout-actions">
                        <button
                            className="btn-pay"
                            onClick={handlePago}
                            disabled={procesando}
                        >
                            {procesando ? t.procesando : t.procesar}
                        </button>
                        <button
                            className="btn-back"
                            onClick={() => navigate('/home')}
                            disabled={procesando}
                        >
                            {t.volver}
                        </button>
                    </div>
                </div>
            </main>

            <footer className="App-footer">
                <div>© IES José Zerpa - Cafetería</div>
            </footer>
        </div>
    );
}

export default Pago;
